import{_ as s,C as n,o as l,c as d,aj as r,G as o,j as e,a as i}from"./chunks/framework.BwH0p-pt.js";const v=JSON.parse('{"title":"Configurable Product","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/products/configurable.md","filePath":"2.0/products/configurable.md","lastUpdated":1781079046000}'),c={name:"2.0/products/configurable.md"};function u(h,t,p,g,b,f){const a=n("ImagePopup");return l(),d("div",null,[t[0]||(t[0]=r('<h1 id="configurable-product" tabindex="-1">Configurable Product <a class="header-anchor" href="#configurable-product" aria-label="Permalink to &quot;Configurable Product&quot;">​</a></h1><p>A <strong>Configurable Product</strong> is a single catalog entry that groups multiple variants — each with its own SKU — under one parent. It&#39;s what you use when one product comes in several <em>options</em> (size, colour, material) and you want all those options managed together instead of as disconnected Simple Products.</p><h2 id="what-is-a-configurable-product" tabindex="-1">What is a Configurable Product? <a class="header-anchor" href="#what-is-a-configurable-product" aria-label="Permalink to &quot;What is a Configurable Product?&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Configurable Product</th></tr></thead><tbody><tr><td><strong>Structure</strong></td><td>One parent SKU + N child variants (each with its own SKU).</td></tr><tr><td><strong>When to use it</strong></td><td>The item has variations — T-shirts in S/M/L × Red/Blue/Green, shoes in different sizes, phone cases in different colours.</td></tr><tr><td><strong>Typical examples</strong></td><td>A T-shirt sold in 3 sizes × 4 colours, a sofa in 3 fabric options, a laptop in multiple storage tiers.</td></tr><tr><td><strong>Compare with</strong></td><td><a href="./simple.html">Simple Product</a> — use that when there are no variants or each variant is genuinely a separate product.</td></tr></tbody></table><p>The attributes that define the variants are called <strong>super attributes</strong> (or <em>configurable attributes</em>) — these are the axes along which the product varies (e.g., <code>size</code>, <code>color</code>). Every other attribute (description, category, images, associations) is edited on the parent and inherited by variants unless you override it.</p><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>A Configurable Product is created in three phases:</p><ol><li><strong>Create the parent</strong> — set product type to <code>Configurable</code>, pick a family, enter a SKU, and choose the <strong>super attributes</strong> that will define variants.</li><li><strong>Fill in parent attributes</strong> — description, categories, images, pricing, associations. Everything that should be shared across variants goes here.</li><li><strong>Add variants</strong> — in the <strong>Variations</strong> section, create one child per combination (e.g., <code>Size=M, Color=Red</code>). Each child has its own SKU and can override variant-specific values.</li></ol><p>At runtime, the parent acts as the public-facing record and the variants hold the option-specific data (and often their own stock, price, image).</p><h2 id="how-to-create-a-configurable-product" tabindex="-1">How to Create a Configurable Product <a class="header-anchor" href="#how-to-create-a-configurable-product" aria-label="Permalink to &quot;How to Create a Configurable Product&quot;">​</a></h2><h3 id="step-1-—-start-creation" tabindex="-1">Step 1 — Start creation <a class="header-anchor" href="#step-1-—-start-creation" aria-label="Permalink to &quot;Step 1 — Start creation&quot;">​</a></h3><ol><li>Click <strong>Catalog → Products</strong>.</li><li>Click <strong>Create Product</strong> in the top-right corner. The <strong>&quot;Create New Product&quot;</strong> dialog opens.</li><li>Fill in: <ul><li><strong>Type</strong> — <code>Configurable</code>.</li><li><strong>Family</strong> — the attribute family that controls which fields appear on the parent.</li><li><strong>SKU</strong> — the parent SKU (must be unique).</li></ul></li><li>Click <strong>Save Product</strong>.</li></ol>',12)),o(a,{src:"/assets/2.0/images/configurable-product/configurable.png",alt:"Create Configurable Product modal"}),t[1]||(t[1]=e("p",null,"UnoPim redirects you to the edit page and prompts you to select super attributes.",-1)),t[2]||(t[2]=e("h3",{id:"step-2-—-pick-super-attributes",tabindex:"-1"},[i("Step 2 — Pick super attributes "),e("a",{class:"header-anchor",href:"#step-2-—-pick-super-attributes","aria-label":'Permalink to "Step 2 — Pick super attributes"'},"​")],-1)),t[3]||(t[3]=e("p",null,[i("Super attributes are the axes the product varies along — typically ones with Select or Multiselect data types (e.g., "),e("code",null,"size"),i(", "),e("code",null,"color"),i("). Only attributes flagged as "),e("em",null,"usable for variants"),i(" on the family appear here.")],-1)),o(a,{src:"/assets/2.0/images/configurable-product/configurableAttributes.png",alt:"Configurable Super Attributes"}),t[4]||(t[4]=r('<p>v2.0 also supports:</p><ul><li><strong>Flexible super attribute selection</strong> during product creation.</li><li><strong><code>variants_json</code></strong> format for programmatic / bulk variant definition.</li><li><strong>Size-based variant seeder</strong> for generating size grids quickly.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Super attributes are <strong>locked after variants are created</strong>. Plan the variant axes up front — changing them later requires deleting and recreating variants.</p></div><h3 id="step-3-—-fill-in-parent-attributes" tabindex="-1">Step 3 — Fill in parent attributes <a class="header-anchor" href="#step-3-—-fill-in-parent-attributes" aria-label="Permalink to &quot;Step 3 — Fill in parent attributes&quot;">​</a></h3><p>Like a Simple Product, the parent edit page groups attributes by <strong>Attribute Group</strong> (General, Descriptions, Categories, Associations, …). Exactly which groups appear depends on the family.</p><p>The <code>default</code> family requires at minimum:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>SKU</strong></td><td>Parent SKU — the identifier for the configurable record.</td></tr><tr><td><strong>Name</strong></td><td>Display name shared by all variants.</td></tr><tr><td><strong>URL Key</strong></td><td>URL-safe slug for storefront linking.</td></tr></tbody></table><p>Other sections to fill on the parent:</p><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Short Description</strong></td><td>Variant-agnostic summary.</td></tr><tr><td><strong>Description</strong></td><td>Full copy — usually shared across variants.</td></tr><tr><td><strong>Technical</strong></td><td>Status toggle — enables/disables the whole configurable set.</td></tr><tr><td><strong>Categories</strong></td><td>Category assignment for the configurable (applies to all variants).</td></tr><tr><td><strong>Associations</strong></td><td>Related / Up-sell / Cross-sell products (see below).</td></tr></tbody></table><p>Each section renders as its own card on the edit page. The <strong>Description</strong> cards carry a WYSIWYG editor. The <strong>Technical</strong> card holds the green <strong>Status</strong> toggle — leaving it disabled takes the whole configurable (parent <strong>and</strong> all variants) offline. The <strong>Categories</strong> card opens a tree picker; anything you select here applies to every variant.</p>',10)),o(a,{src:"/assets/2.0/images/configurable-product/editProduct.png",alt:"Configurable Product Edit Page"}),t[5]||(t[5]=r('<h3 id="step-4-—-add-variants" tabindex="-1">Step 4 — Add variants <a class="header-anchor" href="#step-4-—-add-variants" aria-label="Permalink to &quot;Step 4 — Add variants&quot;">​</a></h3><p>Scroll to the <strong>Variations</strong> section and click <strong>Add Product</strong> to create a child variant. A modal opens with one input per super attribute plus a <strong>SKU</strong> field for the variant itself.</p><p>For each variant:</p><ol><li>Enter the values for the super attributes (e.g., <code>Size = M</code>, <code>Color = Red</code>).</li><li>Enter the variant SKU.</li><li>Optionally override any variant-specific fields (price, image, stock).</li><li>Click <strong>Add</strong> to save the variant. It appears in a table under the Variations section alongside any siblings you&#39;ve already created.</li></ol>',4)),o(a,{src:"/assets/2.0/images/configurable-product/addVariant.png",alt:"Add Variant form"}),t[6]||(t[6]=r('<p>You can add as many variants as the product needs. A T-shirt with Size × Color = 3 × 4 needs 12 variants; the size-based seeder can speed this up.</p><h3 id="step-5-—-add-associations" tabindex="-1">Step 5 — Add associations <a class="header-anchor" href="#step-5-—-add-associations" aria-label="Permalink to &quot;Step 5 — Add associations&quot;">​</a></h3><p>At the bottom of the parent edit page, link this configurable to other products:</p><table tabindex="0"><thead><tr><th>Association</th><th>When to use it</th></tr></thead><tbody><tr><td><strong>Related Products</strong></td><td>Similar alternatives customers may also like.</td></tr><tr><td><strong>Up-Sell Products</strong></td><td>Higher-end versions — a premium jacket line, a faster laptop.</td></tr><tr><td><strong>Cross-Sell Products</strong></td><td>Complementary items — socks with shoes, cables with electronics.</td></tr></tbody></table><p>For each section, click <strong>Add</strong>, search by SKU, select, and confirm. All three association cards accept as many products as you need.</p><h3 id="step-6-—-save" tabindex="-1">Step 6 — Save <a class="header-anchor" href="#step-6-—-save" aria-label="Permalink to &quot;Step 6 — Save&quot;">​</a></h3><p>Click <strong>Save Product</strong> in the top-right of the edit page. You&#39;re redirected back to the <strong>Products Data Grid</strong>, where the configurable appears with <em>Configurable</em> in the <strong>Type</strong> column. The variants don&#39;t show as separate rows — they&#39;re accessible only through the parent&#39;s <strong>Variations</strong> section.</p>',7)),o(a,{src:"/assets/2.0/images/configurable-product/datagrid.png",alt:"Configurable Product in Datagrid"}),t[7]||(t[7]=r('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Attributes with a <strong>channel badge</strong> hold values per channel; with a <strong>locale badge</strong>, per locale; with both, per channel <strong>and</strong> per locale. This applies to the parent and to variants.</p></div><h2 id="working-with-a-configurable-product-after-creation" tabindex="-1">Working with a Configurable Product after creation <a class="header-anchor" href="#working-with-a-configurable-product-after-creation" aria-label="Permalink to &quot;Working with a Configurable Product after creation&quot;">​</a></h2><p>Configurable products support the same lifecycle features as Simple Products — completeness, translation, bulk edit, history, export, copy. A few behaviours are specific to configurables:</p><h3 id="completeness" tabindex="-1">Completeness <a class="header-anchor" href="#completeness" aria-label="Permalink to &quot;Completeness&quot;">​</a></h3><p>The completeness engine evaluates <strong>both the parent and its variants</strong>. The aggregated score accounts for missing required attributes at either level, so even a well-filled parent with an empty variant can drag the score down.</p><ul><li>Completeness is calculated per channel <strong>and</strong> per locale.</li><li>The Dashboard&#39;s <strong>Completeness</strong> widget rolls up all products, including configurables.</li><li>Low-completeness variants are flagged for attention alongside the parent.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Fill in the parent attributes first (description, images, categories). Then sweep through variants to set the variant-specific values (SKU, price, per-variant image). Working top-down is faster than jumping between variants.</p></div><h3 id="translation" tabindex="-1">Translation <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Translation&quot;">​</a></h3><p>Locale-specific fields on the parent and on each variant can be translated manually (locale switcher at the top of the edit page) or automatically via <strong><a href="./../magic-ai/settings.html">Magic AI — Settings</a></strong> Translation. The same workflow applies to both product types — see <a href="./simple.html#translate-values-across-locales">Simple Product → Translate values across locales</a>.</p><h3 id="bulk-edit" tabindex="-1">Bulk edit <a class="header-anchor" href="#bulk-edit" aria-label="Permalink to &quot;Bulk edit&quot;">​</a></h3><p>Use <strong>Bulk Edit</strong> on the Products listing to update attributes across many configurable products at once. Select the rows, pick the attribute, enter the value, apply. See <a href="./simple.html#bulk-edit">Simple Product → Bulk edit</a>.</p><h3 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h3><p>Click the <strong>History</strong> tab on the parent edit page for an audit trail of every change — attribute edits, status flips, category changes, association changes. Each entry lists the date, the user, and the specific fields that changed with before-and-after values. Each variant has its own history accessible from its individual edit view.</p><h3 id="quick-export" tabindex="-1">Quick Export <a class="header-anchor" href="#quick-export" aria-label="Permalink to &quot;Quick Export&quot;">​</a></h3><p>Select the configurable(s) in <strong>Catalog → Products</strong> and use <strong>Quick Export</strong> (top-right, next to Create Product) to download in CSV, XLS, or XLSX. The export bundles the parent record with its variants in a single file, so importing the result back recreates the full configurable structure. For scheduled or filtered exports, use the full <strong><a href="./../data-transfer/export.html">Export</a></strong> workflow.</p><h2 id="related-reading" tabindex="-1">Related reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related reading&quot;">​</a></h2><ul><li><strong><a href="./simple.html">Simple Product</a></strong> — for standalone SKUs with no variants.</li><li><strong><a href="./../attribute/attribute-family.html">Attribute Family</a></strong> — controls which attributes (including candidate super attributes) a configurable can use.</li><li><strong><a href="./../attribute/product-attribute.html">Product Attribute</a></strong> — how to mark an attribute as usable for variants.</li><li><strong><a href="./../magic-ai/settings.html">Magic AI — Settings</a></strong> — auto-translate variant content across locales.</li><li><strong><a href="./../ai-agent/ai-agent-chat.html">AI Agent Chat</a></strong> — v2.0-beta.1 introduced AI Agent support for creating and managing configurable products via chat.</li></ul>',17))])}const S=s(c,[["render",u]]);export{v as __pageData,S as default};
